<template><div><div class="page-head"><div><h1>Expense Report</h1><p>See where operating cash is going and which categories need attention.</p></div><div class="action-row"><input v-model="from" class="input" type="date"><input v-model="to" class="input" type="date"><button class="btn btn-primary" @click="load">Refresh</button></div></div><div class="card metric max-w-sm"><div class="metric-label">Total expenses</div><div class="metric-value mt-2">{{money(data.total)}}</div><div class="metric-trend mt-3">Selected period</div></div><div class="card mt-4 overflow-hidden"><table class="data-table"><thead><tr><th>Category</th><th class="text-right">Amount</th><th class="text-right">Share</th></tr></thead><tbody><tr v-for="x in data.by_category||[]" :key="x.name"><td>{{x.name}}</td><td class="text-right">{{money(x.total)}}</td><td class="text-right">{{share(x.total)}}%</td></tr><tr v-if="!(data.by_category||[]).length"><td colspan="3"><div class="empty">No expenses in this period.</div></td></tr></tbody></table></div></div></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {api} from '../../services/api';const d=new Date(),from=ref(new Date(d.getFullYear(),d.getMonth(),1).toISOString().slice(0,10)),to=ref(d.toISOString().slice(0,10)),data=ref<any>({total:0,by_category:[]});function money(v:any){return new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(Number(v||0))}function share(v:any){return ((Number(v||0)/Math.max(1,Number(data.value.total||0)))*100).toFixed(1)}async function load(){data.value=(await api.get('/reports/expenses',{params:{from:from.value,to:to.value}})).data}onMounted(load)</script>
